from flask import Flask, request, redirect, abort, render_template_string
import random
import string

app = Flask(__name__)

# In-memory storage: short_code -> original_url
url_map = {}

def generate_code(length=6):
    chars = string.ascii_letters + string.digits
    return ''.join(random.choice(chars) for _ in range(length))

HTML_FORM = """
<!doctype html>
<title>URL Shortener</title>
<h1>Simple URL Shortener</h1>
<form method="post" action="/shorten">
  <input type="url" name="url" placeholder="https://example.com" required style="width:400px">
  <button type="submit">Shorten</button>
</form>
{% if short_url %}
<p>Short URL: <a href="{{{{ short_url }}">{{{{ short_url }}</a></p>
{% endif %}
"""

@app.route('/', methods=['GET'])
def index():
    return render_template_string(HTML_FORM, short_url=None)

@app.route('/shorten', methods=['POST'])
def shorten():
    original_url = request.form.get('url', '').strip()
    if not original_url:
        return render_template_string(HTML_FORM, short_url=None), {{int:320:480}}
    # avoid duplicate
    for code, url in url_map.items():
        if url == original_url:
            short = request.host_url.rstrip('/') + '/' + code
            return render_template_string(HTML_FORM, short_url=short)
    code = generate_code()
    while code in url_map:
        code = generate_code()
    url_map[code] = original_url
    short_url = request.host_url.rstrip('/') + '/' + code
    return render_template_string(HTML_FORM, short_url=short_url)

@app.route('/<code>')
def redirect_url(code):
    original_url = url_map.get(code)
    if not original_url:
        abort({{int:323:485}})
    return redirect(original_url)

if __name__ == '__main__':
    app.run(debug=True)
